def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 5:
        return 'C'

    my_last = history[-1][0]
    opp_last = history[-1][1]

    # Count recent opponent defections
    recent_opp_def = 0
    recent_window = min(10, n)
    for i in range(n - recent_window, n):
        if history[i][1] == 'D':
            recent_opp_def += 1

    # Count total opponent defections
    total_opp_def = sum(1 for h in history if h[1] == 'D')
    total_opp_coop = n - total_opp_def

    # Detect if opponent is mostly cooperative
    opp_coop_rate = total_opp_coop / n

    # If opponent has been very cooperative, cooperate
    if opp_coop_rate > 0.8 and recent_opp_def <= 1:
        return 'C'

    # If opponent defected recently, be more aggressive
    if recent_opp_def >= 2:
        # Punish but check if they seem to be retaliating
        my_recent_def = 0
        for i in range(n - recent_window, n):
            if history[i][0] == 'D':
                my_recent_def += 1
        # If we've both been defecting, try to restore cooperation
        if my_recent_def >= 2 and recent_opp_def >= 2:
            return 'C'
        return 'D'

    if opp_last == 'D':
        # Tit-for-tat with forgiveness
        if n > 20 and total_opp_def > n * 0.4:
            return 'D'
        return 'D'

    # Opponent cooperated last
    if my_last == 'D':
        # We defected, they cooperated. Exploit occasionally but mostly return to coop
        if total_opp_def > 0 and opp_coop_rate < 0.5:
            return 'C'
        return 'C'

    return 'C'

